import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import star.common.*;
import star.base.report.*;
import star.metrics.*;
import star.base.neo.ClientServerObject;

public class AuditFrozenFluentQuality extends StarMacro {
    static final boolean REOPEN=true;
    static String env(String k){String x=System.getenv(k);if(x==null||x.isEmpty())throw new IllegalArgumentException("Missing "+k);return x;}
    static String safe(String x){if(!x.matches("[A-Za-z0-9_-]+"))throw new IllegalArgumentException("Unsafe basename");return x;}
    static String q(String x){StringBuilder b=new StringBuilder("\"");for(char c:x.toCharArray()){if(c=='"'||c=='\\')b.append('\\').append(c);else if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}
    static String sha(File f)throws Exception{if(!Files.isRegularFile(f.toPath(),LinkOption.NOFOLLOW_LINKS))throw new IOException("Regular nonlink file required");MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(f.toPath())){byte[] buf=new byte[65536];int n;while((n=in.read(buf))>0)d.update(buf,0,n);}StringBuilder b=new StringBuilder();for(byte v:d.digest())b.append(String.format("%02x",v&255));return b.toString();}
    static void same(String a,String b){if(b==null||!b.matches("[a-f0-9]{64}")||!a.equals(b))throw new IllegalStateException("Exact hash mismatch");}
    static File owned(File dir,String name)throws Exception{File f=new File(dir,name);if(!f.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile())||Files.isSymbolicLink(f.toPath()))throw new IllegalStateException("Outside isolated job");return f;}
    static void unused(File f){if(Files.exists(f.toPath(),LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("Output exists "+f.getName());}
    static void write(File f,String s)throws Exception{try(OutputStream o=Files.newOutputStream(f.toPath(),StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){o.write(s.getBytes(StandardCharsets.UTF_8));}}
    static long integer(String k){String x=env(k);if(!x.matches("[0-9]+"))throw new IllegalArgumentException("Invalid count");long v=Long.parseLong(x);long cap=k.equals("NEUTRAL_INTERIOR_FACES")?3000000:k.equals("NEUTRAL_BOUNDARY_FACES")?200000:k.equals("NEUTRAL_BOUNDARY_COUNT")?16:1000000;if(v<1||v>cap)throw new IllegalArgumentException("Count outside column contract cap");return v;}
    static String unique(String body,String key){java.util.regex.Matcher all=java.util.regex.Pattern.compile(java.util.regex.Pattern.quote("\""+key+"\"")).matcher(body);int n=0;while(all.find())n++;if(n!=1)throw new IllegalStateException("Missing/duplicate key "+key);java.util.regex.Matcher m=java.util.regex.Pattern.compile(java.util.regex.Pattern.quote("\""+key+"\"")+"\\s*:\\s*\"([A-Za-z0-9_-]+)\"").matcher(body);if(!m.find())throw new IllegalStateException("Invalid certificate "+key);return m.group(1);}
    static boolean uniqueBoolean(String text,String key){java.util.regex.Matcher all=java.util.regex.Pattern.compile(java.util.regex.Pattern.quote("\""+key+"\"")).matcher(text);int n=0;while(all.find())n++;if(n!=1)throw new IllegalStateException("Missing/duplicate bool "+key);java.util.regex.Matcher m=java.util.regex.Pattern.compile(java.util.regex.Pattern.quote("\""+key+"\"")+"\\s*:\\s*(true|false)(?=\\s*[,}])").matcher(text);if(!m.find())throw new IllegalStateException("Invalid bool "+key);return Boolean.parseBoolean(m.group(1));}
    static void noFlow(Simulation s){if(s.isInitialized()||s.getSimulationIterator().getCurrentIteration()!=0||!s.getInterfaceManager().getObjects().isEmpty())throw new IllegalStateException("No-flow/interface state required");for(Continuum c:s.getContinuumManager().getObjects()){if(!(c instanceof PhysicsContinuum)||!c.getClass().getName().equals("star.common.PhysicsContinuum"))throw new IllegalStateException("Unexpected continuum");for(Model m:((PhysicsContinuum)c).getModelManager().getObjects())if(!m.getClass().getName().equals("star.metrics.ThreeDimensionalModel"))throw new IllegalStateException("Flow models prohibited");}}
    static String continua(Simulation s){StringBuilder b=new StringBuilder("[");for(Continuum c:s.getContinuumManager().getObjects()){if(b.length()>1)b.append(',');b.append("{\"class\":").append(q(c.getClass().getName())).append(",\"name\":").append(q(c.getPresentationName())).append(",\"models\":[");int n=0;for(Model m:((PhysicsContinuum)c).getModelManager().getObjects()){if(n++>0)b.append(',');b.append(q(m.getClass().getName()));}b.append("]}");}return b.append(']').toString();}
    static String inventory(Simulation s){noFlow(s);FvRepresentation v=(FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh");if(v==null||!v.is3D()||v.isAtLeastOne2D()||s.getRegionManager().getRegions().size()!=1)throw new IllegalStateException("One native3D region required");Region r=s.getRegionManager().getRegions().iterator().next();FvRegion fv=v.getFvRegionManager().getFvRegion(r);if(fv==null||!fv.is3D()||!v.describesRegion(r))throw new IllegalStateException("Native FV identity");
        if(v.getCellCount()!=integer("NEUTRAL_CELLS")||v.getVertexCount()!=integer("NEUTRAL_VERTICES")||v.getInteriorFaceCount()!=integer("NEUTRAL_INTERIOR_FACES"))throw new IllegalStateException("Native global counts differ: cells="+v.getCellCount()+", vertices="+v.getVertexCount()+", interior="+v.getInteriorFaceCount());
        if(fv.getCellCount()!=v.getCellCount()||fv.getVertexCount()!=v.getVertexCount()||fv.getInteriorFaceCount()!=v.getInteriorFaceCount())throw new IllegalStateException("Native local/global counts differ");
        double[] ext=s.getMeshManager().getRegionExtents(r);if(ext.length!=6)throw new IllegalStateException("Missing extents");for(double x:ext)if(!Double.isFinite(x))throw new IllegalStateException("Nonfinite extents");
        StringBuilder bs=new StringBuilder("[");long faces=0;for(Boundary b:r.getBoundaryManager().getBoundaries()){if(!b.getDependentInterfaces().isEmpty())throw new IllegalStateException("Unexpected boundary interface");FvBoundary fb=fv.getFvBoundaries().getFvBoundary(b);if(fb==null||fb.getFaceCount()<1)throw new IllegalStateException("Empty FV boundary");faces+=fb.getFaceCount();if(bs.length()>1)bs.append(',');bs.append("{\"name\":").append(q(b.getPresentationName())).append(",\"type\":").append(q(b.getBoundaryType().getClass().getName())).append(",\"faces\":").append(fb.getFaceCount()).append('}');}bs.append(']');
        if(faces!=integer("NEUTRAL_BOUNDARY_FACES")||r.getBoundaryManager().getBoundaries().size()!=integer("NEUTRAL_BOUNDARY_COUNT"))throw new IllegalStateException("Native boundary counts differ: faces="+faces+", count="+r.getBoundaryManager().getBoundaries().size()+", inventory="+bs);
        if(s.getContinuumManager().getObjects().size()>1)throw new IllegalStateException("Unexpected continuum count");
        return "{\"region_name\":"+q(r.getPresentationName())+",\"cells\":"+v.getCellCount()+",\"vertices\":"+v.getVertexCount()+",\"interior_faces\":"+v.getInteriorFaceCount()+",\"boundary_faces\":"+faces+",\"native_region_extents_raw_interleaved\":"+Arrays.toString(ext)+",\"boundaries\":"+bs+",\"continua\":"+continua(s)+",\"initialized\":false,\"iteration\":0,\"interfaces\":0}";
    }

    static FieldFunction field(Simulation s,FvRepresentation mesh,Class<?> type){for(FieldFunction f:s.getFieldFunctionManager().getScalarFieldFunctions(mesh))if(type.isInstance(f))return f;throw new IllegalStateException("Missing native mesh function "+type.getName());}
    static double measure(Simulation s,FvRepresentation mesh,Region r,FieldFunction f,String type,java.util.List<ClientServerObject> temps){ScalarReport v=s.getReportManager().create(type);temps.add(v);v.setRepresentation(mesh);v.setFieldFunction(f);v.getParts().setObjects(r);double x=v.getReportMonitorValue();if(!Double.isFinite(x))throw new IllegalStateException("Nonfinite mesh measurement");return x;}
    @Override public void execute(){File fail=null;java.util.List<ClientServerObject> temps=new ArrayList<>();PhysicsContinuum space=null;Model added=null;String phase="GUARD";try{
        Simulation s=getActiveSimulation();String run=safe(env("NEUTRAL_RUN_ID")),base=safe(env("NEUTRAL_BASE"));File dir=new File(env("AIR3B_JOB_DIR"));if(!dir.getCanonicalPath().equals("C:\\CodexCFDRestricted\\"+run))throw new IllegalStateException("Wrong owned job");
        File spec=owned(dir,"case_spec.json"),meshFile=owned(dir,base+".msh"),audit=owned(dir,"mesh-audit.json"),checkpoint=owned(dir,base+".sim"),producer=owned(dir,base+"-reopen.json"),record=owned(dir,base+"-quality.json");fail=owned(dir,base+"-quality-failure.json");unused(record);unused(fail);
        same(sha(spec),env("NEUTRAL_SPEC_SHA"));same(sha(meshFile),env("NEUTRAL_MESH_SHA"));same(sha(audit),env("NEUTRAL_AUDIT_SHA"));String inputHash=sha(checkpoint),producerHash=sha(producer);if(!new File(s.getSessionPath()).getCanonicalFile().equals(checkpoint.getCanonicalFile()))throw new IllegalStateException("Wrong loaded checkpoint");String p=Files.readString(producer.toPath(),StandardCharsets.UTF_8);if(!unique(p,"status").equals("ok")||!unique(p,"scope").equals("FLUENT_MESH_EXCHANGE_NO_FLOW")||!unique(p,"run_id").equals(run)||!uniqueBoolean(p,"reopen"))throw new IllegalStateException("Reopen producer scope/run/mode");same(unique(p,"checkpoint_sha256"),inputHash);same(unique(p,"spec_sha256"),env("NEUTRAL_SPEC_SHA"));same(unique(p,"mesh_sha256"),env("NEUTRAL_MESH_SHA"));same(unique(p,"mesh_audit_sha256"),env("NEUTRAL_AUDIT_SHA"));
        String before=inventory(s);Region r=s.getRegionManager().getRegions().iterator().next();FvRepresentation mesh=(FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh");
        // Mesh scalar functions require explicit space metadata; no flow or initialization.
        if(s.getContinuumManager().getObjects().size()!=1)throw new IllegalStateException("One metadata continuum required");space=(PhysicsContinuum)s.getContinuumManager().getObjects().iterator().next();Model existingSpace=null;for(Model m:space.getModelManager().getObjects())if(m instanceof ThreeDimensionalModel){if(existingSpace!=null)throw new IllegalStateException("Duplicate existing space metadata");existingSpace=m;}if(existingSpace==null){space.enable(ThreeDimensionalModel.class);for(Model m:space.getModelManager().getObjects())if(m instanceof ThreeDimensionalModel){if(added!=null)throw new IllegalStateException("Duplicate space metadata");added=m;}if(added==null)throw new IllegalStateException("Space metadata not created");}
        phase="ACTUAL_NATIVE_METRICS";noFlow(s);ElementCountReport count=s.getReportManager().create("star.base.report.ElementCountReport");temps.add(count);count.setRepresentation(mesh);count.getParts().setObjects(r);StringBuilder keys=new StringBuilder("{");for(String key:count.getCountKeys(r)){if(keys.length()>1)keys.append(',');keys.append(q(key)).append(':').append(count.getCount(r,key));}keys.append('}');
        FieldFunction cqf=field(s,mesh,CellQualityFunction.class);double cq=measure(s,mesh,r,cqf,"star.base.report.MinReport",temps),fv=measure(s,mesh,r,field(s,mesh,FaceValidityFunction.class),"star.base.report.MinReport",temps),vc=measure(s,mesh,r,field(s,mesh,VolumeChangeFunction.class),"star.base.report.MinReport",temps);double average=measure(s,mesh,r,cqf,"star.base.report.VolumeAverageReport",temps);if(average<=0)throw new IllegalStateException("Nonpositive quality average");double volume=measure(s,mesh,r,cqf,"star.base.report.VolumeIntegralReport",temps)/average;if(!Double.isFinite(volume)||volume<=0)throw new IllegalStateException("Invalid native volume");
        s.deleteObjects(temps);temps.clear();if(added!=null){space.disableModel(added);added=null;}String after=inventory(s);if(!before.equals(after))throw new IllegalStateException("Native metadata/count drift after reports");same(sha(spec),env("NEUTRAL_SPEC_SHA"));same(sha(meshFile),env("NEUTRAL_MESH_SHA"));same(sha(audit),env("NEUTRAL_AUDIT_SHA"));same(sha(checkpoint),inputHash);same(sha(producer),producerHash);
        boolean passed=cq>=1e-5&&fv>=1.0&&vc>=0.01;
        write(record,"{\"status\":\"ok\",\"scope\":\"FLUENT_NATIVE_QUALITY_MEASUREMENT_ONLY\",\"run_id\":"+q(run)+",\"checkpoint_sha256\":"+q(inputHash)+",\"producer_sha256\":"+q(producerHash)+",\"spec_sha256\":"+q(sha(spec))+",\"cells\":"+mesh.getCellCount()+",\"native_element_counts\":"+keys+",\"measured_cell_quality_min\":"+cq+",\"measured_face_validity_min\":"+fv+",\"measured_volume_change_min\":"+vc+",\"native_volume_m3\":"+volume+",\"quality_gate_passed\":"+passed+",\"cell_quality_gate\":1e-5,\"face_validity_gate\":1.0,\"volume_change_gate\":0.01,\"before\":"+before+",\"after\":"+after+",\"checkpoint_and_inputs_unchanged\":true,\"temporary_space_metadata_restored\":true,\"nearwall_verified\":false,\"flow_physics_verified\":false,\"initialized\":false,\"iteration\":0,\"CFD_admitted\":false,\"E_verified\":false}");System.out.println("FLUENT_NATIVE_QUALITY_RECORDED");
    }catch(Exception e){if(fail!=null)try{write(fail,"{\"status\":\"failed\",\"phase\":"+q(phase)+",\"cause\":"+q(String.valueOf(e))+",\"partials_preserved\":true}");}catch(Exception x){e.addSuppressed(x);}throw new RuntimeException("Column quality audit rejected",e);}finally{Simulation s=getActiveSimulation();if(!temps.isEmpty())s.deleteObjects(temps);if(added!=null&&space!=null)space.disableModel(added);}}
}
